// swift-tools-version: 6.0

import PackageDescription

let package = Package(
    name: "PopupView",
    platforms: [
        .iOS(.v17),
        .macOS(.v14),
        .tvOS(.v17),
        .watchOS(.v10)
    ],
    products: [
        .library(name: "PopupView", targets: ["PopupView"]),
    ],
    dependencies: [],
    targets: [
        .target(
            name: "PopupView",
            dependencies: [],
            swiftSettings: [
              .enableExperimentalFeature("StrictConcurrency")
            ]
        ),
        .testTarget(name: "PopupViewTests", dependencies: ["PopupView"])
    ]
)

//
//  PublicAPI.swift
//  PopupView
//
//  Created by Alisa Mylnikova on 28.03.2025.
//

import SwiftUI

public class Popup {

    public enum PopupType {
        /// Always centered on the screen, ignoring the safe area — a classic modal/alert dialog.
        case `default`
        /// Pinned to an edge (`.bottom` unless repositioned) and always ignores the safe area, so its
        /// background can bleed to the screen edges. Read `popupSafeAreaInsets` from the environment
        /// to inset your own content (e.g. text) away from notches/home indicators/dual-screen cutouts.
        case toast
        /// A freely positioned card. When `useSafeAreaInset` is true (the default) it's kept fully
        /// inside the safe area — including centered positions, which then center within the safe
        /// rect rather than the raw screen, so they won't look screen-centered under asymmetric insets.
        case floater(verticalPadding: CGFloat = 10, horizontalPadding: CGFloat = 10, useSafeAreaInset: Bool = true)

public enum DisplayMode: Identifiable {
    case overlay // place the popup above the content in an .overlay
    case sheet // using .fullscreenSheet
    case window // using UIWindow

    public var id: Self { self }
}

public func dragToDismiss(_ dragToDismiss: Bool) -> Self {
    self.dragToDismiss = dragToDismiss
    return self
}

/// Minimum distance to drag to dismiss
public func dragToDismissDistance(_ dragToDismissDistance: CGFloat) -> Self {
    self.dragToDismissDistance = dragToDismissDistance
    return self
}

/// Should close on tap - default is `true`
/// NOTE: any gesture or control element you add to popup's body will override tap to close. in this case please close the popup manually if you need it to
public func closeOnTap(_ closeOnTap: Bool) -> Self {
    self.closeOnTap = closeOnTap
    return self
}

/// Should close on tap outside - default is `false`
public func closeOnTapOutside(_ closeOnTapOutside: Bool) -> Self {
    self.closeOnTapOutside = closeOnTapOutside
    return self
}

//
//  PopupView.swift
//  PopupView
//
//  Created by Alisa Mylnikova on 23/04/2020.
//  Copyright © 2020 Exyte. All rights reserved.
//

    private var presenterRect: CGRect {
#if os(iOS)
        params.displayMode == .overlay ? presenterContentRect : ScreenUtils.bounds
#else
        // on non-iOS platforms the popup is always rendered in a ZStack within the presenter
        presenterContentRect
#endif
    }
